10	// LookupIP -
11	func LookupIP(ctx context.Context, name string) (string, error) {
12		i, err := LookupIPs(ctx, name)
13		if err != nil {
14			return "", err
15		}
16		if len(i) == 0 {
17			return "", nil
18		}
19		return i[0], nil
20	}
21	
22	// LookupIPs -
23	func LookupIPs(ctx context.Context, name string) ([]string, error) {
24		resolver := &net.Resolver{}
25		srcIPs, err := resolver.LookupIPAddr(ctx, name)
26		if err != nil {
27			return nil, err
28		}
29	
30		// perf note: this slice is not really worth pre-allocating - srcIPs tends
31		// to be very small, and LookupIPAddr is relatively expensive
32		var ips []string
33		for _, v := range srcIPs {
34			if v.IP.To4() != nil {
35				s := v.IP.String()
36				if !slices.Contains(ips, s) {
37					ips = append(ips, s)
38				}
39			}
40		}
41		return ips, nil
42	}
