func ParseIPRange(s string) (IPRange, error) {
	i := strings.IndexByte(s, '-')
	if i < 0 {
		return IPRange{}, fmt.Errorf("no hyphen in range %q", s)
	}
	from, to := s[:i], s[i+1:]
	fromAddr, err := netip.ParseAddr(from)
	if err != nil {
