// Package net implements gomplate's `net` template-function namespace.
//
// The Lookup* functions are thin wrappers over the standard library resolver
// (via the shared gomplate/net helpers). ParseAddr and ParsePrefix return
// net/netip values whose methods are callable from templates. ParseRange
// returns an IPRange, a from-scratch re-implementation of the observable
// behaviour of go4.org/netipx.IPRange (which cannot be used here because
// only the standard library is available). The CIDR* functions mirror the
// reference's Terraform-style CIDR arithmetic.
//
// Coercion notes (matching the reference binary): non-string arguments are
// stringified with fmt's %v semantics, except nil which becomes the string
// "nil". Number arguments are parsed leniently (base-prefix aware integers,
// floats truncated toward zero, booleans as 0/1) and report
// "could not convert ..." errors on failure.
package net

import (
	"context"
	"encoding/json"
	"fmt"
	"math/big"
	stdnet "net"
	"net/netip"
	"strconv"
	"strings"

	gnet "gomplate/net"
)

// NS returns the namespace object whose methods are the `net` template
// functions.
func NS() any {
	return &ns{}
}

type ns struct{}

// toString coerces a template value to a string. nil becomes "nil",
// strings pass through, and everything else uses fmt's %v semantics
// (which also honours fmt.Stringer).
func toString(in any) string {
	if in == nil {
		return "nil"
	}
	if s, ok := in.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", in)
}

// toInt64E coerces a template value to an int64, using the same lenient
// parsing as the shared num helpers but reporting conversion failures the
// way the reference does.
func toInt64E(in any) (int64, error) {
	switch n := in.(type) {
	case int:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int64:
		return n, nil
	case uint:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	case string:
		return stringToInt64E(n)
	case json.Number:
		return stringToInt64E(n.String())
	}
	return 0, fmt.Errorf("could not convert %v to int64", in)
}

func stringToInt64E(s string) (int64, error) {
	trimmed := strings.TrimSpace(s)
	if i, err := strconv.ParseInt(trimmed, 0, 64); err == nil {
		return i, nil
	}
	f, err := strconv.ParseFloat(trimmed, 64)
	if err != nil {
		return 0, fmt.Errorf("could not convert %q to int64: %w", s, err)
	}
	return int64(f), nil
}

// parsePrefixArg coerces a prefix argument: netip.Prefix values pass
// through, everything else is stringified and parsed.
func parsePrefixArg(in any) (netip.Prefix, error) {
	if p, ok := in.(netip.Prefix); ok {
		return p, nil
	}
	return netip.ParsePrefix(toString(in))
}

// LookupIP implements net.LookupIP: resolves the first IPv4 address for the
// given host name.
func (n *ns) LookupIP(name any) (string, error) {
	return gnet.LookupIP(context.Background(), toString(name))
}

// LookupIPs implements net.LookupIPs: resolves all IPv4 addresses for the
// given host name, as an array of strings.
func (n *ns) LookupIPs(name any) ([]string, error) {
	return gnet.LookupIPs(context.Background(), toString(name))
}

// LookupCNAME implements net.LookupCNAME: resolves the canonical name for
// the given host name.
func (n *ns) LookupCNAME(name any) (string, error) {
	return gnet.LookupCNAME(toString(name))
}

// LookupSRV implements net.LookupSRV: resolves the first SRV record for the
// given service name.
func (n *ns) LookupSRV(name any) (*stdnet.SRV, error) {
	return gnet.LookupSRV(toString(name))
}

// LookupSRVs implements net.LookupSRVs: resolves all SRV records for the
// given service name.
func (n *ns) LookupSRVs(name any) ([]*stdnet.SRV, error) {
	return gnet.LookupSRVs(toString(name))
}

// LookupTXT implements net.LookupTXT: resolves all TXT records for the
// given host name.
func (n *ns) LookupTXT(name any) ([]string, error) {
	return gnet.LookupTXT(toString(name))
}

// ParseAddr implements net.ParseAddr: parses the stringified input as an IP
// address. netip.Addr inputs pass through unchanged. Parse errors match the
// reference, which reports them without the "netip." package prefix.
func (n *ns) ParseAddr(addr any) (netip.Addr, error) {
	if a, ok := addr.(netip.Addr); ok {
		return a, nil
	}
	a, err := netip.ParseAddr(toString(addr))
	if err != nil {
		return netip.Addr{}, fmt.Errorf("%s", strings.TrimPrefix(err.Error(), "netip."))
	}
	return a, nil
}

// ParsePrefix implements net.ParsePrefix: parses the stringified input as an
// IP address prefix. netip.Prefix inputs pass through unchanged.
func (n *ns) ParsePrefix(prefix any) (netip.Prefix, error) {
	return parsePrefixArg(prefix)
}

// ParseRange implements net.ParseRange: parses the stringified input as an
// inclusive IP address range ("from-to"). IPRange inputs pass through
// unchanged.
func (n *ns) ParseRange(iprange any) (IPRange, error) {
	if r, ok := iprange.(IPRange); ok {
		return r, nil
	}
	return ParseIPRange(toString(iprange))
}

// CIDRHost implements net.CIDRHost: calculates the full host IP address for
// hostnum within the given prefix. Negative host numbers wrap once from the
// end of the range (e.g. -1 is the last address).
func (n *ns) CIDRHost(hostnum, prefix any) (netip.Addr, error) {
	p, err := parsePrefixArg(prefix)
	if err != nil {
		return netip.Addr{}, err
	}
	num, err := toInt64E(hostnum)
	if err != nil {
		return netip.Addr{}, fmt.Errorf("expected a number: %w", err)
	}

	p = p.Masked()
	addrBits := p.Addr().BitLen()
	hostBits := uint(addrBits - p.Bits())

	space := new(big.Int).Lsh(big.NewInt(1), hostBits)
	host := big.NewInt(num)
	if num < 0 {
		host.Add(host, space)
	}
	if host.Sign() < 0 || host.Cmp(space) >= 0 {
		return netip.Addr{}, fmt.Errorf("prefix of %d does not accommodate a host numbered %s", p.Bits(), host)
	}

	base := addrToBig(p.Addr())
	base.Add(base, host)
	return bigToAddr(base, p.Addr().Is4()), nil
}

// CIDRNetmask implements net.CIDRNetmask: the subnet mask of the given
// prefix as an IP address in conventional notation.
func (n *ns) CIDRNetmask(prefix any) (netip.Addr, error) {
	p, err := parsePrefixArg(prefix)
	if err != nil {
		return netip.Addr{}, err
	}

	bits := p.Bits()
	if p.Addr().Is4() {
		var m [4]byte
		fillMask(m[:], bits)
		return netip.AddrFrom4(m), nil
	}
	var m [16]byte
	fillMask(m[:], bits)
	return netip.AddrFrom16(m), nil
}

func fillMask(b []byte, bits int) {
	for i := 0; i < bits; i++ {
		b[i/8] |= 1 << (7 - uint(i%8))
	}
}

// CIDRSubnets implements net.CIDRSubnets: calculates the 2^newbits
// consecutive subnet prefixes of equal length obtained by extending the
// given prefix by newbits bits.
func (n *ns) CIDRSubnets(newbits, prefix any) ([]netip.Prefix, error) {
	p, err := parsePrefixArg(prefix)
	if err != nil {
		return nil, err
	}
	nb, err := toInt64E(newbits)
	if err != nil {
		return nil, fmt.Errorf("newbits must be a number: %w", err)
	}
	if nb < 1 {
		return nil, fmt.Errorf("must extend prefix by at least one bit")
	}

	p = p.Masked()
	addrBits := p.Addr().BitLen()
	newLen := int64(p.Bits()) + nb
	if newLen > int64(addrBits) {
		return nil, fmt.Errorf("insufficient address space to extend prefix of %d by %d", p.Bits(), nb)
	}

	count := uint64(1) << uint(nb)
	step := new(big.Int).Lsh(big.NewInt(1), uint(addrBits)-uint(newLen))
	base := addrToBig(p.Addr())
	is4 := p.Addr().Is4()

	out := make([]netip.Prefix, 0, count)
	cur := new(big.Int)
	for i := uint64(0); i < count; i++ {
		cur.Mul(step, new(big.Int).SetUint64(i))
		cur.Add(cur, base)
		out = append(out, netip.PrefixFrom(bigToAddr(cur, is4), int(newLen)))
	}
	return out, nil
}

// CIDRSubnetSizes implements net.CIDRSubnetSizes: calculates a sequence of
// consecutive subnet prefixes within the given prefix, each extending the
// prefix length by the corresponding newbits value. The prefix is the last
// argument; all preceding arguments are newbits values.
func (n *ns) CIDRSubnetSizes(args ...any) ([]netip.Prefix, error) {
	if len(args) < 2 {
		return nil, fmt.Errorf("wrong number of args: want 2 or more, got %d", len(args))
	}

	p, err := parsePrefixArg(args[len(args)-1])
	if err != nil {
		return nil, err
	}

	newbits := make([]int64, len(args)-1)
	for i, a := range args[:len(args)-1] {
		nb, err := toInt64E(a)
		if err != nil {
			return nil, fmt.Errorf("newbits must be numbers: %w", err)
		}
		newbits[i] = nb
	}

	p = p.Masked()
	addrBits := p.Addr().BitLen()
	is4 := p.Addr().Is4()
	family := "IPv6"
	if is4 {
		family = "IPv4"
	}

	base := addrToBig(p.Addr())
	end := new(big.Int).Lsh(big.NewInt(1), uint(addrBits-p.Bits()))
	end.Add(end, base)
	end.Sub(end, big.NewInt(1))

	out := make([]netip.Prefix, 0, len(newbits))
	cur := new(big.Int).Set(base)
	prev := ""
	for _, nb := range newbits {
		if nb < 1 {
			return nil, fmt.Errorf("must extend prefix by at least one bit")
		}
		if nb > 32 {
			return nil, fmt.Errorf("may not extend prefix by more than 32 bits")
		}
		newLen := int64(p.Bits()) + nb
		if newLen > int64(addrBits) {
			return nil, fmt.Errorf("would extend prefix to %d bits, which is too long for an %s address", newLen, family)
		}
		size := new(big.Int).Lsh(big.NewInt(1), uint(addrBits)-uint(newLen))
		last := new(big.Int).Add(cur, size)
		last.Sub(last, big.NewInt(1))
		if last.Cmp(end) > 0 {
			return nil, fmt.Errorf("not enough remaining address space for a subnet with a prefix of %d bits after %s", newLen, prev)
		}
		subnet := netip.PrefixFrom(bigToAddr(cur, is4), int(newLen))
		out = append(out, subnet)
		prev = subnet.String()
		cur.Add(cur, size)
	}
	return out, nil
}

// addrToBig interprets an address as a big unsigned integer.
func addrToBig(a netip.Addr) *big.Int {
	if a.Is4() {
		b := a.As4()
		return new(big.Int).SetBytes(b[:])
	}
	b := a.As16()
	return new(big.Int).SetBytes(b[:])
}

// bigToAddr converts a big unsigned integer back to an address, as a 4-byte
// address when is4 is true and a 16-byte address otherwise.
func bigToAddr(i *big.Int, is4 bool) netip.Addr {
	if is4 {
		var b [4]byte
		i.FillBytes(b[:])
		return netip.AddrFrom4(b)
	}
	var b [16]byte
	i.FillBytes(b[:])
	return netip.AddrFrom16(b)
}

package net

import (
	"fmt"
	"math/big"
	"net/netip"
	"strings"
)

// IPRange is an inclusive range of IP addresses of the same address family.
// It re-implements the observable behaviour of go4.org/netipx.IPRange (an
// external module that cannot be used here) using only the standard library.
// The method set matches the version vendored in the reference binary:
// From, To, String, IsValid, IsZero, Contains, Overlaps, Prefix and
// Prefixes.
type IPRange struct {
	from netip.Addr
	to   netip.Addr
}

// IPRangeFrom returns the IPRange from from to to.
func IPRangeFrom(from, to netip.Addr) IPRange {
	return IPRange{from: from, to: to}
}

// ParseIPRange parses a string of the form "from-to" as an IPRange. The
// error texts mirror those of the reference implementation.
func ParseIPRange(s string) (IPRange, error) {
	i := strings.IndexByte(s, '-')
	if i < 0 {
		return IPRange{}, fmt.Errorf("no hyphen in range %q", s)
	}
	from, to := s[:i], s[i+1:]
	fromAddr, err := netip.ParseAddr(from)
	if err != nil {
		return IPRange{}, fmt.Errorf("invalid From IP %q in range %q", from, s)
	}
	toAddr, err := netip.ParseAddr(to)
	if err != nil {
		return IPRange{}, fmt.Errorf("invalid To IP %q in range %q", to, s)
	}
	r := IPRange{fromAddr, toAddr}
	if !r.IsValid() {
		return IPRange{}, fmt.Errorf("range %s to %s not valid", from, to)
	}
	return r, nil
}

// From returns the lower bound of the range.
func (r IPRange) From() netip.Addr {
	return r.from
}

// To returns the upper bound of the range.
func (r IPRange) To() netip.Addr {
	return r.to
}

// String returns the range in "from-to" form, or "invalid IPRange" when the
// range is not valid.
func (r IPRange) String() string {
	if !r.IsValid() {
		return "invalid IPRange"
	}
	return fmt.Sprintf("%s-%s", r.from, r.to)
}

// IsValid reports whether the range is non-empty, with both bounds valid
// and in the same address family.
func (r IPRange) IsValid() bool {
	return r.from.IsValid() &&
		r.to.IsValid() &&
		r.from.Is4() == r.to.Is4() &&
		!r.to.Less(r.from)
}

// IsZero reports whether the range is the zero value.
func (r IPRange) IsZero() bool {
	return !r.from.IsValid() && !r.to.IsValid()
}

// Contains reports whether the range contains the given address.
func (r IPRange) Contains(ip netip.Addr) bool {
	return r.IsValid() &&
		ip.IsValid() &&
		r.from.Is4() == ip.Is4() &&
		!ip.Less(r.from) &&
		!r.to.Less(ip)
}

// Overlaps reports whether the two ranges share any addresses.
func (r IPRange) Overlaps(o IPRange) bool {
	return r.IsValid() &&
		o.IsValid() &&
		r.from.Is4() == o.from.Is4() &&
		!r.to.Less(o.from) &&
		!o.to.Less(r.from)
}

// Prefix returns the range as a single prefix, if the range is exactly one
// prefix; otherwise it returns the zero Prefix and false.
func (r IPRange) Prefix() (netip.Prefix, bool) {
	prefixes := r.Prefixes()
	if len(prefixes) != 1 {
		return netip.Prefix{}, false
	}
	return prefixes[0], true
}

// Prefixes returns the minimal set of prefixes that exactly cover the
// range, in ascending order. It returns nil for an invalid range.
func (r IPRange) Prefixes() []netip.Prefix {
	if !r.IsValid() {
		return nil
	}
	bits := r.from.BitLen()
	is4 := r.from.Is4()
	from := addrToBig(r.from)
	to := addrToBig(r.to)

	var out []netip.Prefix
	cur := new(big.Int).Set(from)
	one := big.NewInt(1)
	for cur.Cmp(to) <= 0 {
		// the largest block aligned to cur is 2^(trailing zero bits)
		align := trailingZeros(cur, bits)
		// the largest block that fits in the remaining addresses
		remaining := new(big.Int).Sub(to, cur)
		remaining.Add(remaining, one)
		fit := remaining.BitLen() - 1
		block := align
		if fit < block {
			block = fit
		}
		out = append(out, netip.PrefixFrom(bigToAddr(cur, is4), bits-block))
		cur.Add(cur, new(big.Int).Lsh(one, uint(block)))
	}
	return out
}

// trailingZeros returns the number of trailing zero bits in i, capped at
// max (which is returned when i is zero).
func trailingZeros(i *big.Int, max int) int {
	if i.Sign() == 0 {
		return max
	}
	n := 0
	for n < max && i.Bit(n) == 0 {
		n++
	}
	return n
}

