package net

import (
	"bytes"
	"os/exec"
	"strings"
	"testing"
	"text/template"
)

// TestAgainstReference renders every template below with this package and
// with the reference binary, and compares byte-for-byte. For failing
// templates the reference's "error calling <Name>: <text>" tail is compared
// against this package's error tail.
func TestAgainstReference(t *testing.T) {
	templates := []string{
		`{{ net.LookupIP "localhost" }}`,
		`{{ net.LookupIPs "localhost" }}`,
		`{{ net.LookupCNAME "localhost" }}`,
		`{{ net.LookupSRV "_sip._udp.localhost" }}`,
		`{{ net.LookupSRVs "_sip._udp.localhost" }}`,
		`{{ net.LookupTXT "localhost" }}`,
		`{{ (net.ParseAddr "192.168.0.1").IsPrivate }}`,
		`{{ (net.ParseAddr "93.184.216.34").Prefix 12 }}`,
		`{{ net.ParseAddr "nonsense" }}`,
		`{{ net.ParseAddr 1.5 }}`,
		`{{ (net.ParsePrefix "192.168.0.0/24").Masked }}`,
		`{{ net.ParsePrefix "fd00::/129" }}`,
		`{{ (net.ParseRange "192.168.0.0-192.168.0.255").To }}`,
		`{{ (net.ParseRange "1.2.3.0-1.2.3.233").Prefixes }}`,
		`{{ (net.ParseRange "::1-::ff").Prefixes }}`,
		`{{ net.ParseRange "10.0.0.5-10.0.0.1" }}`,
		`{{ "10.12.127.0/20" | net.CIDRHost 268 }}`,
		`{{ net.CIDRHost -300 "10.0.0.0/24" }}`,
		`{{ net.CIDRHost -1 "fd00::/126" }}`,
		`{{ net.CIDRHost "abc" "10.0.0.0/24" }}`,
		`{{ net.CIDRNetmask "10.12.127.0/20" }}`,
		`{{ net.CIDRNetmask "fd00:fd12:3456:7890:00a2::/72" }}`,
		`{{ net.CIDRNetmask "::ffff:10.0.0.0/120" }}`,
		`{{ index ("10.0.0.0/16" | net.CIDRSubnets 2) 1 }}`,
		`{{ net.CIDRSubnets 2 "10.0.0.0/16" }}`,
		`{{ net.CIDRSubnets 17 "10.0.0.0/16" }}`,
		`{{ net.CIDRSubnets "abc" "10.0.0.0/16" }}`,
		`{{ net.CIDRSubnetSizes 4 4 8 4 "10.1.0.0/16" }}`,
		`{{ net.CIDRSubnetSizes 8 4 "10.1.0.0/16" }}`,
		`{{ net.CIDRSubnetSizes 8 2 "10.1.0.0/24" }}`,
		`{{ net.CIDRSubnetSizes 1 1 1 "10.0.0.0/24" }}`,
		`{{ net.CIDRSubnetSizes 32 "fd00::/100" }}`,
		`{{ net.CIDRSubnetSizes "10.1.0.0/16" }}`,
		`{{ net.CIDRHost 1 (net.ParsePrefix "10.0.0.0/24") }}`,
		`{{ net.ParseAddr (net.ParseAddr "1.2.3.4") }}`,
		`{{ net.ParseRange (net.ParseRange "1.2.3.4-1.2.3.9") }}`,
		`{{ net.ParseAddr }}`,
		`{{ net.CIDRSubnets 2 3 "10.0.0.0/16" }}`,
	}

	for _, tmpl := range templates {
		t.Run(tmpl, func(t *testing.T) {
			cmd := exec.Command("/workspace/executable", "--experimental", "-i", tmpl)
			var refOut, refErr bytes.Buffer
			cmd.Stdout = &refOut
			cmd.Stderr = &refErr
			refRunErr := cmd.Run()

			var buf bytes.Buffer
			tt, err := template.New("<arg>").Option("missingkey=error").
				Funcs(template.FuncMap{"net": func() any { return NS() }}).Parse(tmpl)
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			myErr := tt.Execute(&buf, map[string]any{})

			if refRunErr == nil {
				if myErr != nil {
					t.Errorf("reference succeeded with %q, mine errored: %v", refOut.String(), myErr)
					return
				}
				if buf.String() != refOut.String() {
					t.Errorf("output mismatch:\n ref: %q\nmine: %q", refOut.String(), buf.String())
				}
				return
			}
			if myErr == nil {
				t.Errorf("reference failed (%s), mine succeeded with %q", refErr.String(), buf.String())
				return
			}
			// compare the tail from "error calling" onward, when present
			refMsg := refErr.String()
			i := strings.Index(refMsg, "error calling")
			if i < 0 {
				t.Logf("reference error has no 'error calling' tail: %s", refMsg)
				return
			}
			refTail := strings.TrimSuffix(strings.TrimSpace(refMsg[i:]), `"}`)
			j := strings.Index(myErr.Error(), "error calling")
			if j < 0 {
				t.Errorf("my error has no 'error calling' tail: %v (ref tail %q)", myErr, refTail)
				return
			}
			myTail := myErr.Error()[j:]
			// lookup errors embed resolver addresses that may differ; compare prefixes
			if strings.HasPrefix(refTail, "error calling Lookup") {
				if !strings.HasPrefix(myTail, refTail[:len("error calling LookupXx")]) {
					t.Errorf("error mismatch:\n ref: %q\nmine: %q", refTail, myTail)
				}
				return
			}
			if myTail != refTail {
				t.Errorf("error mismatch:\n ref: %q\nmine: %q", refTail, myTail)
			}
		})
	}
}

